package com.bookstore.bike.controller;
import com.bookstore.bike.entity.*; import com.bookstore.bike.repo.UserRepository; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.nio.charset.StandardCharsets; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users; private final PasswordEncoder encoder; private final javax.crypto.SecretKey key; @Value("${campusride.jwt.expiration}") long expiration;
 public AuthController(UserRepository u,PasswordEncoder e,@Value("${campusride.jwt.secret}")String secret){users=u;encoder=e;key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}
 public record Register(@NotBlank String fullName,@Email @NotBlank String email,@Size(min=8) String password,String phone,String college,String studentId,String city){} public record Login(@Email String email,String password){}
 @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody Register r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.status(409).body(Map.of("error","Email already registered")); User u=new User();u.setFullName(r.fullName());u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setPhone(r.phone());u.setCollege(r.college());u.setStudentId(r.studentId());u.setCity(r.city());users.save(u);return ResponseEntity.status(201).body(Map.of("message","Registration submitted for verification"));}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Login r){User u=users.findByEmail(r.email()).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.getPassword()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");String token=Jwts.builder().subject(u.getEmail()).claim("role",u.getRole().name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiration)).signWith(key).compact();return Map.of("token",token,"user",Map.of("id",u.getId(),"name",u.getFullName(),"email",u.getEmail(),"role",u.getRole(),"verificationStatus",u.getVerificationStatus()));}
}
